local CrumhornMaker = {}
local PRODUCTS = {
    soprano_crumhorn = { name = "Soprano krumhorn", woodCost = 1, reedCost = 1, leatherCost = 1, time = 2, cost = 25, soundQuality = 9, prestige = 1, description = "Soprano krumhorn z usnjato kapo." },
    alto_crumhorn = { name = "Alt krumhorn", woodCost = 2, reedCost = 1, leatherCost = 1, time = 3, cost = 70, soundQuality = 12, prestige = 2, description = "Alt krumhorn z značilnim zvokom." },
    tenor_crumhorn = { name = "Tenor krumhorn", woodCost = 2, reedCost = 1, leatherCost = 1, brassCost = 1, time = 5, cost = 180, soundQuality = 16, prestige = 4, happiness = 1, description = "Tenor krumhorn z medeninastim koncem." },
    bass_crumhorn = { name = "Bas krumhorn", woodCost = 3, reedCost = 2, leatherCost = 1, brassCost = 1, time = 7, cost = 400, soundQuality = 20, prestige = 8, happiness = 2, description = "Bas krumhorn z ukrivljenim koncem." },
    great_bass_crumhorn = { name = "Veliki bas krumhorn", woodCost = 4, reedCost = 2, leatherCost = 1, brassCost = 1, time = 9, cost = 850, soundQuality = 24, prestige = 13, happiness = 3, description = "Veliki bas krumhorn za slovesne koncerte." },
    royal_crumhorn_consort = { name = "Kraljevski krumhorn konzort", woodCost = 5, goldCost = 1, silverCost = 1, ivoryCost = 1, reedCost = 3, leatherCost = 2, time = 13, cost = 2000, soundQuality = 36, prestige = 50, happiness = 10, description = "Veliki kraljevski komplet krumhornov z zlatim in slonokoščenim okovjem." },
}
local BUILDINGS = {
    workshop = { name = "Krumhornska delavnica", cost = { gold = 250, wood = 120 }, upkeep = 6, qualityBonus = 5 },
    boring_room = { name = "Vrtalnica", cost = { gold = 800, wood = 220, stone = 200, brass = 6 }, upkeep = 20, qualityBonus = 18 },
    cap_room = { name = "Kapnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, leather = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_crumhorn_atelier = { name = "Kraljevski atelje krumhornov", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, ivory = 20 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
CrumhornMaker.woodStock = 14; CrumhornMaker.reedStock = 12; CrumhornMaker.leatherStock = 10; CrumhornMaker.brassStock = 8; CrumhornMaker.silverStock = 6; CrumhornMaker.goldStock = 6; CrumhornMaker.ivoryStock = 6
CrumhornMaker.productStock = {}; CrumhornMaker.buildings = {}; CrumhornMaker.maker = nil; CrumhornMaker.activeMaking = {}; CrumhornMaker.totalProducts = 0; CrumhornMaker.dayTimer = 0
function CrumhornMaker.init() CrumhornMaker.woodStock=14; CrumhornMaker.reedStock=12; CrumhornMaker.leatherStock=10; CrumhornMaker.brassStock=8; CrumhornMaker.silverStock=6; CrumhornMaker.goldStock=6; CrumhornMaker.ivoryStock=6; CrumhornMaker.productStock={}; CrumhornMaker.buildings={}; CrumhornMaker.maker=nil; CrumhornMaker.activeMaking={}; CrumhornMaker.totalProducts=0; CrumhornMaker.dayTimer=0; print("[CrumhornMaker] Royal Crumhorn Maker System initialized (6 products, 4 buildings)") end
function CrumhornMaker.hireMaker(n,s) s=s or math.random(50,90); local c=470+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrumhornMaker.maker={name=n or ("Krumhornar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krumhornar najet: %s (spretnost: %d)",CrumhornMaker.maker.name,s),"success") end; return true end
function CrumhornMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrumhornMaker.build(id) local ok,e=CrumhornMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrumhornMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrumhornMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrumhornMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrumhornMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and CrumhornMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.reedCost and CrumhornMaker.reedStock<(d.reedCost or 0) then return false,"Premalo trobil" end; if d.leatherCost and CrumhornMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.brassCost and CrumhornMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and CrumhornMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrumhornMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.ivoryCost and CrumhornMaker.ivoryStock<(d.ivoryCost or 0) then return false,"Premalo slonovine" end; if #CrumhornMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CrumhornMaker.maker then return false,"Potreben krumhornar" end; return true end
function CrumhornMaker.make(pt,qty) qty=qty or 1; local ok,e=CrumhornMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then CrumhornMaker.woodStock=CrumhornMaker.woodStock-d.woodCost*qty end; if d.reedCost then CrumhornMaker.reedStock=CrumhornMaker.reedStock-d.reedCost*qty end; if d.leatherCost then CrumhornMaker.leatherStock=CrumhornMaker.leatherStock-d.leatherCost*qty end; if d.brassCost then CrumhornMaker.brassStock=CrumhornMaker.brassStock-d.brassCost*qty end; if d.silverCost then CrumhornMaker.silverStock=CrumhornMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrumhornMaker.goldStock=CrumhornMaker.goldStock-d.goldCost*qty end; if d.ivoryCost then CrumhornMaker.ivoryStock=CrumhornMaker.ivoryStock-d.ivoryCost*qty end; local t=d.time; if CrumhornMaker.maker then t=math.max(1,t-math.floor(CrumhornMaker.maker.skill/12)) end; table.insert(CrumhornMaker.activeMaking,{id="crumhorn_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrumhornMaker.completeMaking(m) local q=1.0+(CrumhornMaker.getQualityBonus()/100); if CrumhornMaker.maker then q=q+(CrumhornMaker.maker.skill/180) end; q=math.min(2.0,q); CrumhornMaker.productStock[m.productType]=(CrumhornMaker.productStock[m.productType] or 0)+m.quantity; CrumhornMaker.totalProducts=CrumhornMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrumhornMaker.maker then CrumhornMaker.maker.itemsMade=CrumhornMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CrumhornMaker.maker.skill=math.min(100,CrumhornMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krumhorn izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crumhorn.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function CrumhornMaker.update(dt) if not _G.state then return end; CrumhornMaker.dayTimer=CrumhornMaker.dayTimer+dt; if CrumhornMaker.dayTimer>=30 then CrumhornMaker.dayTimer=0; for i=#CrumhornMaker.activeMaking,1,-1 do local m=CrumhornMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrumhornMaker.completeMaking(m); table.remove(CrumhornMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrumhornMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrumhornMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrumhornMaker.getStats() return {woodStock=CrumhornMaker.woodStock,reedStock=CrumhornMaker.reedStock,leatherStock=CrumhornMaker.leatherStock,brassStock=CrumhornMaker.brassStock,silverStock=CrumhornMaker.silverStock,goldStock=CrumhornMaker.goldStock,ivoryStock=CrumhornMaker.ivoryStock,productStock=CrumhornMaker.productStock,numBuildings=#CrumhornMaker.buildings,hasMaker=CrumhornMaker.maker~=nil,makerName=CrumhornMaker.maker and CrumhornMaker.maker.name or "—",makerSkill=CrumhornMaker.maker and CrumhornMaker.maker.skill or 0,activeMaking=#CrumhornMaker.activeMaking,totalProducts=CrumhornMaker.totalProducts} end
return CrumhornMaker
